window.MOTIF_CATALOG_CHUNKS[37]={"cards":[{"id":"MEJE-KW-001474","row_version":1,"title":"기독교 신앙을 암시만 하는 인물","original":"Ambiguously Christian","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"기도나 명절 같은 단서가 있어도 인물이 어떤 신앙을 지니는지 직접 말하지 않는 설정. 관습적 표현만으로 교파나 믿음의 깊이를 단정하지 않는다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-001474/index.html"},{"id":"MEJE-KW-001475","row_version":2,"title":"선한지 악한지 확정되지 않은 인물","original":"Ambiguously Evil","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"인물의 행동과 소문이 서로 어긋나 도덕적 위치를 쉽게 판정할 수 없는 상태. 명백한 선택이 나오기 전까지 관객의 경계심을 유지한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-001475/index.html"},{"id":"MEJE-KW-001476","row_version":2,"title":"동성애 가능성을 열어 둔 인물","original":"Ambiguously Gay","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"동성 인물에 대한 애정으로 읽힐 장면이 있지만 작품이 인물의 성적 지향을 확정하지 않는 설정. 말투나 친밀함만으로 정체성을 판정하지 않는다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-001476/index.html"},{"id":"MEJE-KW-001477","row_version":1,"title":"인간인지 알 수 없는 인물","original":"Ambiguously Human","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"겉모습과 행동은 사람과 닮았지만 종족이나 출생의 단서가 어긋나 인간인지 확정되지 않는 존재. 불확실성이 세계의 경계를 드러낸다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-001477/index.html"},{"id":"MEJE-KW-001478","row_version":2,"title":"유대교 배경을 암시만 하는 인물","original":"Ambiguously Jewish","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"인물의 종교·문화적 배경을 확정하지 않은 채 일부 단서만 제시하는 설정. 고정관념을 근거로 실제 정체성을 단정하는 해석과 구별한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-001478/index.html"},{"id":"MEJE-KW-001479","row_version":1,"title":"친척인지 분명하지 않은 두 인물","original":"Ambiguously Related","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10","ML-T00970"],"summary":"두 인물이 닮았거나 가족처럼 지내지만 혈연 여부 또는 관계의 종류가 확정되지 않는 설정. 어느 쪽 친척인지 모르는 방문객과 달리 친척이라는 전제 자체도 열려 있다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"가족·친족","entry_url":"cards/MEJE-KW-001479/index.html"},{"id":"MEJE-KW-001480","row_version":1,"title":"의식이 있는지 모르는 물건","original":"Ambiguously Sentient Object","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"사물이 스스로 생각하는 듯한 반응을 보이지만 실제 의식이 있는지는 끝내 분명하지 않은 설정. 의인화된 표현과 살아 있는 존재 사이를 오간다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-001480/index.html"},{"id":"MEJE-KW-001481","row_version":1,"title":"훈련받았는지 알 수 없는 인물","original":"Ambiguously Trained","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"인물이 전문 기술을 보여 주지만 언제 어디서 배웠는지, 과거에 어떤 일을 했는지 밝히지 않는 설정. 능력의 출처가 인물의 숨은 이력을 암시한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-001481/index.html"},{"id":"MEJE-KW-001482","row_version":1,"title":"진담인지 장난인지 모를 말","original":"Ambiguously Trolling","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23","ML-T01982","ML-T01991"],"summary":"인물의 말이 상대를 놀리려는 농담인지 실제 믿음이나 고백인지 확정되지 않는 대사. 반응에 따라 관계의 거리와 긴장이 달라진다.","accent":"#7C808E","tab":"#79866C","facet":"서술·언어·정보","bookmark":"중의성","entry_url":"cards/MEJE-KW-001482/index.html"},{"id":"MEJE-KW-001483","row_version":1,"title":"기계인지 생물인지 모를 존재","original":"Ambiguous Robots","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"몸의 일부가 인공물처럼 보이고 일부는 생물처럼 보여 어느 쪽에 속하는지 정해지지 않은 존재. 인간인지 알 수 없는 인물과는 다른 분류의 불확실성을 만든다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-001483/index.html"},{"id":"MEJE-KW-001484","row_version":1,"title":"무슨 일인지 알 수 없는 상황","original":"Ambiguous Situation","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23","ML-T01947","ML-T01952"],"summary":"관객에게 필요한 정보가 빠지거나 단서가 충돌해 현재 사건의 의미를 확정할 수 없는 구성. 인물이 알고 있는 사실과 관객에게 주어진 정보의 차이가 핵심이다.","accent":"#7C808E","tab":"#A58A4E","facet":"서술·언어·정보","bookmark":"정보 생략","entry_url":"cards/MEJE-KW-001484/index.html"},{"id":"MEJE-KW-001485","row_version":2,"title":"악해진 시점을 숨긴 인물","original":"Ambiguous Start of Darkness","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"인물이 언제 어떤 계기로 악한 편에 섰는지 중요한 시점이 화면 밖에 남는 전개. 변화의 원인을 추적할 단서만 주어져 뒤늦은 재해석을 부른다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-001485/index.html"},{"id":"MEJE-KW-001486","row_version":2,"title":"수식 범위가 모호한 문장","original":"Ambiguous Syntax","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23","ML-T01982","ML-T01991"],"summary":"문장의 수식어가 어느 말에 걸리는지 분명하지 않아 둘 이상의 뜻으로 읽히는 언어 장치. 의도된 농담이거나 사건의 오해를 만드는 단서가 된다.","accent":"#7C808E","tab":"#79866C","facet":"서술·언어·정보","bookmark":"중의성","entry_url":"cards/MEJE-KW-001486/index.html"},{"id":"MEJE-KW-001487","row_version":2,"title":"시대를 확정할 수 없는 배경","original":"Ambiguous Time Period","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14","ML-T01236","ML-T01245"],"summary":"연도나 역사적 단서를 일부러 흐리거나 서로 어긋나게 배치해 작품의 시기를 특정하기 어렵게 만드는 배경 설정. 다른 세계의 달력을 쓰는 경우에도 나타날 수 있다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"시대 불명 배경","entry_url":"cards/MEJE-KW-001487/index.html"},{"id":"MEJE-KW-001488","row_version":1,"title":"야망을 악으로 읽는 서사","original":"Ambition Is Evil","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"더 높은 지위나 성취를 바라는 인물이 그 욕망 때문에 타락하거나 벌받도록 만드는 가치 판단. 야망 자체와 타인을 해치는 선택을 구별해 읽어야 한다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-001488/index.html"},{"id":"MEJE-KW-001489","row_version":1,"title":"큰 꿈을 꾸지만 행동하지 않는 인물","original":"Ambitious, but Lazy","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"높은 목표를 말하면서도 이를 위한 꾸준한 노력은 피하는 인물형. 재능이나 운을 기대하는 태도가 사건을 미루거나 다른 사람에게 부담을 넘긴다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-001489/index.html"},{"id":"MEJE-KW-001490","row_version":1,"title":"신앙에 거리감을 둔 성공회 인물","original":"Ambivalent Anglican","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"성공회 신자나 성직자를 교리적 확신보다 일상적 관습과 절제된 태도로 그리는 영국 매체의 표현 관습. 실제 구성원 모두의 믿음을 설명하지는 않는다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001490/index.html"},{"id":"MEJE-KW-001491","row_version":2,"title":"사고를 영업거리로 삼는 변호사","original":"Ambulance Chaser","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09","ML-T00916","ML-T00922"],"summary":"피해 사건을 찾아다니며 소송을 제안하는 기회주의적 변호사형 인물. 법률가의 행동을 풍자하는 캐릭터 관습으로 실제 소송의 일반적 모습을 뜻하지 않는다.","accent":"#7B7594","tab":"#528982","facet":"인물","bookmark":"법률가","entry_url":"cards/MEJE-KW-001491/index.html"},{"id":"MEJE-KW-001492","row_version":2,"title":"사고 직후 구급차로 건너뛰기","original":"Ambulance Cut","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"위험한 행동을 보여 준 뒤 결과 장면을 생략하고 구급차가 달리는 화면으로 바로 전환하는 편집. 사고의 구체적인 모습은 관객의 상상에 맡긴다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-001492/index.html"},{"id":"MEJE-KW-001493","row_version":2,"title":"숨어 있다 뛰쳐나오는 적","original":"Ambushing Enemy","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임에서 주변 환경에 몸을 감춘 적이 플레이어가 가까워지자 갑자기 모습을 드러내는 배치. 사전 단서와 반응할 시간을 얼마나 주는지가 놀람과 공정성을 가른다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-001493/index.html"},{"id":"MEJE-KW-001494","row_version":1,"title":"에이멘 브레이크","original":"Amen Break","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24","ML-T02036","ML-T02040"],"summary":"윈스턴스의 〈Amen, Brother〉에 담긴 짧은 드럼 연주 구절. 다른 음악에서 잘라 쓰고 반복·변형하는 샘플링을 통해 새로운 리듬의 재료가 된 사례다.","accent":"#8A7893","tab":"#528982","facet":"소리·음악","bookmark":"반복 리듬","entry_url":"cards/MEJE-KW-001494/index.html"},{"id":"MEJE-KW-001495","row_version":2,"title":"독립하지 못한 미국의 대체역사","original":"America Is Still a Colony","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13","ML-T01186","ML-T01190"],"summary":"미국의 독립이 이루어지지 않고 유럽 국가의 식민 지배가 계속된다고 가정하는 대체역사 설정. 분기 이후 정치 체제와 생활의 변화를 함께 구성해야 한다.","accent":"#497A73","tab":"#8B739C","facet":"세계관·규칙","bookmark":"바뀌는 역사","entry_url":"cards/MEJE-KW-001495/index.html"},{"id":"MEJE-KW-001496","row_version":1,"title":"미국을 상징하는 흰머리수리","original":"American Eagle","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"미국을 가리키는 시각 표지로 흰머리수리의 모습이나 문양을 쓰는 표현. 동물이 등장할 때는 국적·기관·이념에 대한 암시로도 읽힌다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-001496/index.html"},{"id":"MEJE-KW-001497","row_version":1,"title":"미국 고딕 그림 구도의 변주","original":"American Gothic Couple","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":null,"parent_id":null,"tag_path":["ML-F29"],"summary":"두 사람이 집 앞에 서고 한 사람이 쇠스랑을 든 그림 구도를 다른 인물·소품으로 다시 만드는 시각적 인용. 익숙한 이미지와 바뀐 요소의 차이가 농담이나 비평이 된다.","accent":"#7B876E","tab":"#9A6A55","facet":"기원·전승·참조","bookmark":"분류축","entry_url":"cards/MEJE-KW-001497/index.html"},{"id":"MEJE-KW-001498","row_version":1,"title":"해외 표지에서 강해진 귀여운 인물","original":"American Kirby Is Hardcore","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27","ML-T02277","ML-T02282"],"summary":"한 지역에서 귀엽게 그린 인물을 다른 시장의 홍보 그림에서는 표정·자세·빛을 바꿔 더 거칠게 보이도록 만드는 현지화 관습. 지역 전체의 취향을 하나로 단정하지 않는다.","accent":"#7F8A85","tab":"#528982","facet":"메타·제작·유통","bookmark":"번역과 현지화","entry_url":"cards/MEJE-KW-001498/index.html"},{"id":"MEJE-KW-001499","row_version":2,"title":"미국 상징으로 꾸민 로봇","original":"American Robot","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"국기 색, 별무늬나 애국적 대사를 결합해 미국의 상징처럼 디자인한 로봇. 기계의 국적보다 시각적 기호와 과장된 태도가 핵심이다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-001499/index.html"},{"id":"MEJE-KW-001500","row_version":2,"title":"미국인을 카우보이로 그리기","original":"Americans Are Cowboys","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"미국 출신 인물에게 카우보이 모자와 서부극 복장을 입혀 출신을 단번에 알리는 표현 관습. 실제 생활상의 다양성을 줄인 고정관념이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001500/index.html"},{"id":"MEJE-KW-001501","row_version":1,"title":"본국에서는 인기지만 해외에서는 미움받기","original":"Americans Hate Tingle","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":null,"parent_id":null,"tag_path":["ML-F30"],"summary":"작품이나 인물이 원래 시장에서는 사랑받지만 다른 문화권에서는 거부감을 사는 수용 차이. 번역, 홍보, 문화적 맥락에 따라 같은 특징의 평가가 달라진다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"분류축","entry_url":"cards/MEJE-KW-001501/index.html"},{"id":"MEJE-KW-001502","row_version":2,"title":"제목에 미국을 내세우기","original":"American Title","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"작품 제목에 미국 또는 미국인을 직접 넣어 장소·정체성·이상이나 그에 대한 풍자를 암시하는 명명 방식. 제목만으로 작품의 태도를 확정할 수는 없다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-001502/index.html"},{"id":"MEJE-KW-001503","row_version":2,"title":"세계의 위기를 미국만 해결하기","original":"America Saves the Day","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"전 지구적 문제를 여러 지역에 펼쳐 놓고 해결의 주체를 미국 인물이나 조직에 집중시키는 서사 관습. 다른 사회의 역할이 작게 처리될 수 있다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001503/index.html"},{"id":"MEJE-KW-001504","row_version":2,"title":"미국과 동아시아를 섞은 가상 도시","original":"Americasia","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"미국과 동아시아의 도시·언어·패션 요소를 한 공간에 결합한 세계관 미학. 어느 지역의 요소를 골랐는지 구체적으로 밝히면 막연한 문화 혼합을 피할 수 있다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-001504/index.html"},{"id":"MEJE-KW-001505","row_version":2,"title":"미국이 세계를 지배한 미래","original":"America Takes Over the World","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"미국의 정치·군사적 영향력이 전 세계의 통치 구조로 커졌다고 가정하는 미래 설정. 세계의 위기를 미국만 해결하기와 달리 위기 해결보다 지배 체제의 결과에 초점을 둔다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-001505/index.html"},{"id":"MEJE-KW-001506","row_version":1,"title":"미국만 전쟁을 이긴 것처럼 그리기","original":"America Won World War II","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"제2차 세계대전의 승리를 미국 혼자 이룬 것처럼 보여 다른 연합국의 역할을 지우는 역사 재현의 편향. 이야기의 시점이 좁은 경우와 사실을 왜곡한 경우를 구별해 읽는다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001506/index.html"},{"id":"MEJE-KW-001507","row_version":2,"title":"주제와 장면을 앞세운 미국식 보드게임","original":"Ameritrash Games","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"구체적인 배경 이야기와 인물, 주사위·카드·모형 같은 구성물을 강조하는 보드게임 흐름. 전략 중심 게임과 대비해 부르는 이름이지만 작품마다 요소의 비율은 다르다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-001507/index.html"},{"id":"MEJE-KW-001508","row_version":1,"title":"듣는 음악으로 인물 소개하기","original":"AM/FM Characterization","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"인물이 선택해 듣는 곡이나 방송을 통해 취향·세대·숨은 면모를 짧게 보여주는 연출. 대사로 직접 설명하지 않고 소리의 선택을 인물 정보로 쓴다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-001508/index.html"},{"id":"MEJE-KW-001509","row_version":2,"title":"친근하게 그린 개미","original":"Amicable Ants","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"의인화된 개미를 협력적이고 호감 가는 인물로 묘사하는 관습. 실제 생태의 특징을 그대로 옮긴 설명이 아니라 작품의 캐릭터 선택이다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-001509/index.html"},{"id":"MEJE-KW-001510","row_version":1,"title":"헤어진 뒤에도 잘 지내는 전 연인","original":"Amicable Exes","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"결별이나 이혼 후에도 서로를 존중하며 우정이나 협력을 이어 가는 관계. 다시 사귀는 것과는 다른 형태의 친밀함을 보여준다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-001510/index.html"},{"id":"MEJE-KW-001511","row_version":1,"title":"나를 진지하게 사랑하느냐는 질문","original":"Am I Just a Toy to You?","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"한 인물이 상대의 애정이 진심인지 잠깐의 관심인지 불안해하며 직접 확인하는 관계 장면. 대답보다 그동안의 행동과 신뢰가 갈등의 무게를 정한다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-001511/index.html"},{"id":"MEJE-KW-001512","row_version":2,"title":"그렇지 않냐고 반응을 구하는 말버릇","original":"Am I Right?","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23","ML-T01993","ML-T01996"],"summary":"농담이나 주장 끝에 상대의 동의를 재촉하는 짧은 질문을 되풀이하는 말버릇. 청중과의 거리를 좁히거나 어색한 침묵을 드러낸다.","accent":"#7C808E","tab":"#AF8665","facet":"서술·언어·정보","bookmark":"말버릇","entry_url":"cards/MEJE-KW-001512/index.html"},{"id":"MEJE-KW-001513","row_version":1,"title":"탄약 보급 장치","original":"Ammo Resupply","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임 속 무기 사용 횟수를 다시 채우는 아이템·능력·보급 지점. 접근 위치와 횟수 제한이 전투의 자원 관리에 영향을 준다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-001513/index.html"},{"id":"MEJE-KW-001514","row_version":1,"title":"탄약이 필요한 근접 무기","original":"Ammo-Using Melee Weapon","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"가까이서 쓰는 무기인데도 동력이나 소모 자원이 떨어지면 기능이 약해지는 허구의 장비. 탄약 보급 장치와 결합하면 자원 관리가 근접 전투에도 적용된다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-001514/index.html"},{"id":"MEJE-KW-001515","row_version":2,"title":"등에 짊어진 탄약 장치","original":"Ammunition Backpack","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"대형 무기나 특수 장비에 필요한 탄약·연료·전력을 등짐 형태로 연결한 인물 디자인. 실루엣과 장비의 규모를 드러내며 이동상의 제약을 암시한다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-001515/index.html"},{"id":"MEJE-KW-001516","row_version":1,"title":"탄약을 아껴 쓰는 인물","original":"Ammunition Conservation","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"한정된 탄약을 의식해 적은 발사로 상황을 넘기려는 전투 인물형. 위기의 길이와 자원 부족을 보여주는 이야기 장치다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-001516/index.html"},{"id":"MEJE-KW-001517","row_version":1,"title":"탄약 저장부의 폭발 연출","original":"Ammunition Detonation","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"작품 속 장비의 탄약 저장부가 공격을 받은 뒤 커다란 폭발로 이어지는 전투 연출. 전장의 위험을 한 장면에 압축하며 실제 장비의 안전 지침을 뜻하지 않는다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-001517/index.html"},{"id":"MEJE-KW-001518","row_version":1,"title":"기억을 잃고 옷차림을 자기 정체로 믿기","original":"Amnesiac Costume Identity","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09","ML-T00948","ML-T00952"],"summary":"기억상실 상태의 인물이 그때 입은 복장이나 변장을 평소의 자기 모습으로 받아들여 새 역할을 만들어 가는 설정. 의상에 붙은 의미가 자기 인식을 대신한다.","accent":"#7B7594","tab":"#79866C","facet":"인물","bookmark":"기억을 잃은 인물","entry_url":"cards/MEJE-KW-001518/index.html"},{"id":"MEJE-KW-001519","row_version":1,"title":"되찾은 기억과 현재 인격의 충돌","original":"Amnesiac Dissonance","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"기억을 잃은 동안 형성한 가치관과 되찾은 과거의 행동이 서로 어긋나 한 인물 안에서 갈등하는 설정. 기억을 잃고 옷차림을 자기 정체로 믿기와 달리 과거를 다시 아는 순간이 핵심이다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-001519/index.html"},{"id":"MEJE-KW-001520","row_version":1,"title":"기억을 잃은 신적 존재","original":"Amnesiac God","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12","ML-T01116","ML-T01117"],"summary":"평범한 사람이라 믿고 살던 인물이 기억을 되찾으며 신에 가까운 정체와 능력을 알아차리는 설정. 잊힌 힘이 돌아오면 세계의 권력 균형과 인물의 책임도 바뀐다.","accent":"#62816F","tab":"#8B739C","facet":"존재·종족","bookmark":"신","entry_url":"cards/MEJE-KW-001520/index.html"},{"id":"MEJE-KW-001521","row_version":1,"title":"기억을 잃은 영웅","original":"Amnesiac Hero","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09","ML-T00899","ML-T00900"],"summary":"자기 이력을 모른 채 사건에 뛰어든 영웅형 인물. 잃어버린 이름과 기술을 찾는 과정이 현재의 선택과 과거의 행적을 연결한다.","accent":"#7B7594","tab":"#8B739C","facet":"인물","bookmark":"영웅","entry_url":"cards/MEJE-KW-001521/index.html"},{"id":"MEJE-KW-001522","row_version":1,"title":"자기 거짓말을 믿게 된 기억상실자","original":"Amnesiac Liar","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09","ML-T00948","ML-T00952"],"summary":"다른 사람에게 거짓 신분을 말한 뒤 기억을 잃어 그 말을 스스로의 과거로 받아들이는 인물. 거짓을 알고 있는 주변 사람과 현재의 자기 인식 사이에 틈이 생긴다.","accent":"#7B7594","tab":"#79866C","facet":"인물","bookmark":"기억을 잃은 인물","entry_url":"cards/MEJE-KW-001522/index.html"},{"id":"MEJE-KW-001523","row_version":1,"title":"연인을 기억하지 못하는 사람","original":"Amnesiac Lover","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10","ML-T00979","ML-T00982"],"summary":"두 사람이 사랑하던 사이였지만 한쪽이 관계의 기억을 잃어 상대를 낯선 사람처럼 대하는 설정. 남은 사람은 추억을 증명하거나 새로운 관계를 다시 쌓아야 한다.","accent":"#9D7C82","tab":"#778F70","facet":"관계","bookmark":"상호 연애","entry_url":"cards/MEJE-KW-001523/index.html"},{"id":"MEJE-KW-001524","row_version":2,"title":"재난의 원인이 자신인 기억상실 주인공","original":"Amnesiac Protagonist Catalyst","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"기억을 잃은 주인공이 위기를 해결하려다 과거의 자신이 바로 그 위기를 일으켰음을 알게 되는 반전. 해결의 목적이 책임을 감당하는 문제로 바뀐다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-001524/index.html"},{"id":"MEJE-KW-001525","row_version":2,"title":"몸에 남은 잊힌 과거의 습관","original":"Amnesiac Resonance","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"기억을 잃은 인물이 이유를 모른 채 과거에 익힌 행동이나 관계의 반응을 되풀이하는 설정. 의식적 기억과 몸에 남은 익숙함의 차이가 단서가 된다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-001525/index.html"},{"id":"MEJE-KW-001526","row_version":2,"title":"기억상실을 순수함으로 보는 관습","original":"Amnesiacs Are Innocent","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"과거를 잊은 인물이 마치 잘못도 욕망도 없는 사람처럼 그려지는 서사 관습. 기억의 상실과 책임·성격의 변화는 서로 다른 문제임을 드러낸다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001526/index.html"},{"id":"MEJE-KW-001527","row_version":1,"title":"기억을 잃고 영웅 편에 선 악역","original":"Amnesiac Villain Joins the Heroes","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"악역이 과거의 적대 관계를 잊은 채 영웅 일행과 협력하는 전개. 기억이 돌아오면 현재 쌓은 관계와 이전의 선택을 다시 판단해야 한다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-001527/index.html"},{"id":"MEJE-KW-001528","row_version":1,"title":"기억하지 못해 피할 수 없는 위기","original":"Amnesia Danger","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":null,"parent_id":null,"tag_path":["ML-F08"],"summary":"인물이 이전에는 해결 방법을 알았지만 그 기억을 잃어 눈앞의 위험에 대응하지 못하는 상황. 지식의 부재가 능력의 부재만큼 큰 장애가 된다.","accent":"#936E72","tab":"#9A6A55","facet":"갈등·장애","bookmark":"분류축","entry_url":"cards/MEJE-KW-001528/index.html"},{"id":"MEJE-KW-001529","row_version":1,"title":"기억상실을 중심에 둔 특별편","original":"Amnesia Episode","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"연속 작품의 한 회차가 인물의 기억상실과 회복을 중심 사건으로 삼는 구성. 익숙한 관계를 잠시 낯설게 만들어 인물들의 역할을 다시 보여준다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-001529/index.html"},{"id":"MEJE-KW-001530","row_version":1,"title":"잊을 때마다 다시 시작되는 조사","original":"Amnesia Loop","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"인물이 비밀을 알아낼 때마다 기억을 지워 다시 같은 단서를 추적하게 되는 반복 구조. 시간 자체가 되감기는 이야기와 달리 세계는 계속 앞으로 간다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-001530/index.html"},{"id":"MEJE-KW-001531","row_version":1,"title":"일부만 남은 기억 지우기","original":"Amnesia Missed a Spot","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"비밀을 감추기 위한 기억 삭제가 완전하지 않아 한 사람이나 핵심 단서가 남는 전개. 남은 조각이 은폐의 취약점을 드러낸다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-001531/index.html"},{"id":"MEJE-KW-001532","row_version":2,"title":"아프리카너를 악역으로만 그리는 편견","original":"Amoral Afrikaner","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"남아프리카의 특정 언어·문화 공동체 출신 인물을 늘 잔혹한 사냥꾼이나 용병으로만 묘사하는 고정관념. 작품 속 악역 표현과 실제 사람들의 다양성을 구별한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001532/index.html"},{"id":"MEJE-KW-001533","row_version":2,"title":"도덕보다 승리를 앞세우는 변호사","original":"Amoral Attorney","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09","ML-T00916","ML-T00922"],"summary":"사건의 진실이나 당사자의 피해보다 수임료·승소·명성을 우선하는 변호사형 인물. 법률가 직업 전체의 모습이 아니라 작품의 악역 또는 풍자적 성격화다.","accent":"#7B7594","tab":"#528982","facet":"인물","bookmark":"법률가","entry_url":"cards/MEJE-KW-001533/index.html"},{"id":"MEJE-KW-001534","row_version":2,"title":"의뢰인을 이용하는 연예 대리인","original":"Amoral Talent Agent","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"예술가의 일을 연결해 주는 지위를 자기 돈과 권력을 위해 이용하는 대리인형 인물. 창작자를 돕는 역할과 착취하는 행동의 차이가 갈등이 된다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-001534/index.html"},{"id":"MEJE-KW-001535","row_version":1,"title":"양서류 떼의 공격","original":"Amphibian Assault","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12","ML-T01108"],"summary":"개구리·두꺼비 같은 양서류를 단순한 배경 동물이 아니라 집단 위협으로 쓰는 허구의 장면. 크기와 행동을 과장해 익숙한 생물에 대한 감각을 뒤집는다.","accent":"#62816F","tab":"#778F70","facet":"존재·종족","bookmark":"동물·식물·균류 계열","entry_url":"cards/MEJE-KW-001535/index.html"},{"id":"MEJE-KW-001536","row_version":1,"title":"거대한 개구리와 두꺼비","original":"Amphibian at Large","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12","ML-T01108","ML-T01112"],"summary":"평소 작게 여기는 양서류를 인물보다 크게 확대해 괴수나 이색 생물로 등장시키는 설정. 양서류 떼의 공격과 달리 크기 자체가 핵심이다.","accent":"#62816F","tab":"#778F70","facet":"존재·종족","bookmark":"거대 동물","entry_url":"cards/MEJE-KW-001536/index.html"},{"id":"MEJE-KW-001537","row_version":1,"title":"물과 육지를 달리는 자동차","original":"Amphibious Automobile","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16","ML-T01454","ML-T01457"],"summary":"도로를 달리다가 수면 위나 물속에서도 움직이는 차량 설정. 어떤 방식으로 환경을 넘는지는 작품의 기술 규칙에 따라 달라진다.","accent":"#8E8263","tab":"#7D8FA3","facet":"사물·도구·자원","bookmark":"자동차","entry_url":"cards/MEJE-KW-001537/index.html"},{"id":"MEJE-KW-001538","row_version":1,"title":"땅과 물을 오가는 게임 유닛","original":"Amphibious Unit","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"전략 게임에서 육지와 수역을 모두 이동할 수 있는 부대. 이동 경로의 제약을 줄이는 대신 다른 능력이나 비용으로 균형을 잡을 수 있다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-001538/index.html"},{"id":"MEJE-KW-001539","row_version":1,"title":"평범한 동물의 과장된 지능","original":"Amplified Animal Aptitude","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12","ML-T01108","ML-T01109"],"summary":"작품 속 일반 동물이 인간의 말과 의도를 지나치게 잘 이해하고 복잡한 문제까지 해결하는 묘사. 말을 하는 동물이나 문명화된 동물과는 다른 경계에 놓인다.","accent":"#62816F","tab":"#778F70","facet":"존재·종족","bookmark":"현실 동물","entry_url":"cards/MEJE-KW-001539/index.html"},{"id":"MEJE-KW-001540","row_version":1,"title":"기존 능력을 키워 주는 유물","original":"Amplifier Artifact","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"새 능력을 주기보다 착용자에게 이미 있던 힘을 크게 증폭하는 유물. 사용자의 기본 능력과 유물의 작용을 구별해야 설정이 선명해진다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-001540/index.html"},{"id":"MEJE-KW-001541","row_version":2,"title":"감염 확산을 막으려 절단하는 전개","original":"Amputation Stops Spread","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"허구의 감염이나 저주가 퍼지기 전에 신체 일부를 포기해 위기를 멈추려는 극단적 장면. 생존을 위한 선택의 대가를 다루는 서사 장치이며 실제 의료 판단을 뜻하지 않는다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-001541/index.html"},{"id":"MEJE-KW-001542","row_version":2,"title":"신체 훼손을 형벌로 쓰는 사회","original":"Amputative Sentencing","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"작품 속 국가나 집단이 범죄에 대한 처벌로 신체 일부를 훼손하도록 정한 제도. 권력의 잔혹함과 처벌의 낙인을 보여주는 세계관 설정이다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-001542/index.html"},{"id":"MEJE-KW-001543","row_version":1,"title":"지니기만 해도 강해지는 장신구","original":"Amulet of Concentrated Awesome","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16","ML-T01436"],"summary":"소유하거나 착용하는 것만으로 인물의 전투력과 자신감이 크게 달라지는 물건. 실제 힘의 원천인지 믿음의 효과인지는 이야기마다 다르다.","accent":"#8E8263","tab":"#A58A4E","facet":"사물·도구·자원","bookmark":"의복·장신구","entry_url":"cards/MEJE-KW-001543/index.html"},{"id":"MEJE-KW-001544","row_version":1,"title":"떼어 낼 수 없는 힘의 장신구","original":"Amulet of Dependency","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16","ML-T01436"],"summary":"강한 힘을 얻는 대신 그것에 의존하게 되어 물건을 잃거나 쓰지 못하면 삶이 흔들리는 설정. 지니기만 해도 강해지는 장신구의 이득 뒤에 붙은 제약을 강조한다.","accent":"#8E8263","tab":"#A58A4E","facet":"사물·도구·자원","bookmark":"의복·장신구","entry_url":"cards/MEJE-KW-001544/index.html"},{"id":"MEJE-KW-001545","row_version":2,"title":"공포의 놀이공원","original":"Amusement Park of Doom","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"즐거움을 기대하는 놀이공원이 버려진 기구나 함정, 괴물 때문에 위험한 장소로 변한 배경. 환한 장식과 숨은 위협의 대비가 공간의 핵심이다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-001545/index.html"},{"id":"MEJE-KW-001546","row_version":1,"title":"웃음을 맡은 외계인","original":"Amusing Alien","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09","ML-T00880","ML-T00889"],"summary":"낯선 세계에서 왔지만 공포나 지혜보다 희극적 반응을 만드는 일을 주로 맡는 외계 인물. 이질적인 외형과 상황 판단을 웃음의 재료로 쓴다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"희극적 조연","entry_url":"cards/MEJE-KW-001546/index.html"},{"id":"MEJE-KW-001547","row_version":1,"title":"상처가 금세 사라지는 슬랩스틱","original":"Amusing Injuries","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"큰 충격을 받아도 다음 장면에는 멀쩡한 몸으로 돌아오는 희극적 표현 관습. 실제 부상의 결과와 분리된 작품 내부의 과장된 규칙이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001547/index.html"},{"id":"MEJE-KW-001548","row_version":1,"title":"빗나간 공격이 웃음이 되는 인물","original":"Amusingly Awful Aim","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"무기나 물건을 겨누면 목표를 터무니없이 빗맞혀 장면의 긴장을 웃음으로 바꾸는 인물형. 단순한 명중 실패보다 반복되는 과장이 중요하다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-001548/index.html"},{"id":"MEJE-KW-001549","row_version":1,"title":"내용이 거의 없는 목록 농담","original":"Amusingly Short List","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"길게 나열할 듯 소개했지만 항목이 하나뿐이거나 아예 없어서 기대가 무너지는 농담. 목록을 만드는 형식과 실제 분량의 차이가 웃음의 핵심이다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-001549/index.html"},{"id":"MEJE-KW-001550","row_version":1,"title":"옆에서 던진 한마디","original":"Amusing Third-Party Interjection","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"두 사람이 대화하거나 다투는 동안 제삼자가 짧은 말을 끼워 넣어 긴장을 풀거나 더 키우는 장면. 말하는 사람의 위치가 농담의 타이밍을 만든다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-001550/index.html"},{"id":"MEJE-KW-001551","row_version":2,"title":"시간 순서를 뒤섞은 서사","original":"Anachronic Order","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05","ML-T00626","ML-T00632"],"summary":"사건을 실제 발생 순서와 다르게 배열해 앞뒤를 오가며 이야기를 제시하는 구성. 비선형 구조 가운데 시간 배열의 재구성에 초점을 둔다.","accent":"#6A748C","tab":"#8B739C","facet":"서사 구조","bookmark":"비선형 구조","entry_url":"cards/MEJE-KW-001551/index.html"},{"id":"MEJE-KW-001552","row_version":2,"title":"여러 시대가 뒤섞인 세계","original":"Anachronism Stew","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"한 작품 안에 서로 다른 시대의 의상·기술·생활 양식이 함께 존재하는 설정. 의도된 혼합인지 자료 착오인지는 작품의 규칙과 연출에서 판단한다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-001552/index.html"},{"id":"MEJE-KW-001553","row_version":2,"title":"시대에 맞지 않는 동물","original":"Anachronistic Animal","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"과거를 재현한 작품에 그 시기의 장소나 생태와 맞지 않는 동물을 등장시키는 표현. 의도한 시간 이동 설정과 자료 조사에서 생긴 시대 착오를 구별한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001553/index.html"},{"id":"MEJE-KW-001554","row_version":2,"title":"시대 착오를 드러내는 단서","original":"Anachronistic Clue","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"물건의 재료나 말, 기술이 주장된 시대와 맞지 않아 위조나 시간 이동을 의심하게 만드는 단서. 여러 시대가 뒤섞인 세계 전체보다 한 증거물의 불일치에 초점을 둔다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-001554/index.html"},{"id":"MEJE-KW-001555","row_version":1,"title":"시대에 맞지 않는 고아원","original":"Anachronistic Orphanage","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 놓인 사회와 시대의 아동 보호 방식에 맞지 않는 옛 형태의 고아원을 별다른 설명 없이 등장시키는 관습. 익숙한 이미지가 현실적 제도보다 앞설 때 나타난다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001555/index.html"},{"id":"MEJE-KW-001556","row_version":1,"title":"배경 시대와 어긋난 음악","original":"Anachronistic Soundtrack","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"작품 속 시대보다 훨씬 뒤의 음악을 사용하거나 다른 시기의 곡을 의도적으로 배치하는 연출. 극중 인물이 듣는 소리인지 관객만 듣는 배경음인지에 따라 효과가 다르다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-001556/index.html"},{"id":"MEJE-KW-001557","row_version":1,"title":"문장 끝말을 다음 문장 첫머리로 잇기","original":"Anadiplosis","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23","ML-T01982","ML-T01992"],"summary":"앞 구절의 마지막 말이나 표현을 다음 구절의 시작에서 되풀이하는 수사법. 반복된 말이 두 생각을 이어 리듬과 논리의 사슬을 만든다.","accent":"#7C808E","tab":"#79866C","facet":"서술·언어·정보","bookmark":"반복법","entry_url":"cards/MEJE-KW-001557/index.html"},{"id":"MEJE-KW-001558","row_version":2,"title":"모두에게 역할을 주는 모험가 직업군","original":"An Adventurer Is You","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임에서 전사·치유자·마법사처럼 서로 다른 직업 역할을 나눠 플레이어가 팀에 기여하게 하는 설계. 역할의 차이가 협력의 이유가 된다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-001558/index.html"},{"id":"MEJE-KW-001559","row_version":1,"title":"이야기가 전하려는 교훈","original":"An Aesop","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"사건과 인물의 결과를 통해 작품이 관객에게 제시하는 가치 판단이나 배움. 의도와 다른 교훈 해석처럼 독자가 다른 결론을 얻을 가능성도 남는다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-001559/index.html"},{"id":"MEJE-KW-001560","row_version":1,"title":"평범한 이름을 가진 외계인","original":"An Alien Named \"Bob\"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"낯선 종족의 인물이 과장된 외계 이름 대신 익숙한 사람 이름을 쓰는 명명 방식. 예상과 실제 이름의 차이가 웃음이나 친밀함을 만든다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-001560/index.html"},{"id":"MEJE-KW-001561","row_version":1,"title":"되받아치기에 무너진 비유","original":"Analogy Backfire","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"설득하려고 든 비유의 빠진 조건을 다른 인물이 지적해 처음의 주장과 반대되는 뜻이 드러나는 대화. 비유의 허점을 이용해 인물 사이의 힘을 뒤집는다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-001561/index.html"},{"id":"MEJE-KW-001562","row_version":2,"title":"외계인 납치 뒤의 침습적 검사","original":"Anal Probing","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07","ML-T00776","ML-T00780"],"summary":"외계인 납치 서사에서 동의 없는 신체검사를 공포나 농담으로 반복하는 관습. 검사 방법보다 붙잡힌 사람이 자기 몸을 통제할 수 없다는 점이 장면의 긴장이다.","accent":"#9B7160","tab":"#7D8FA3","facet":"사건·행동","bookmark":"납치","entry_url":"cards/MEJE-KW-001562/index.html"},{"id":"MEJE-KW-001563","row_version":1,"title":"작품을 해설하는 영상 에세이 채널","original":"Analysis Channel","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"영상으로 작품의 주제·연출·장르를 분석하는 채널 형식. 짧은 반응보다 근거를 모아 한 관점을 전개하는 설명이 중심이다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-001563/index.html"},{"id":"MEJE-KW-001564","row_version":1,"title":"문장 첫머리 반복","original":"Anaphora","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23","ML-T01982","ML-T01992"],"summary":"연속된 문장이나 구절의 첫머리에 같은 말이나 구조를 되풀이해 리듬과 강조를 만드는 수사법. 문장 끝말을 다음 문장 첫머리로 잇기와 반복 위치가 다르다.","accent":"#7C808E","tab":"#79866C","facet":"서술·언어·정보","bookmark":"반복법","entry_url":"cards/MEJE-KW-001564/index.html"},{"id":"MEJE-KW-001565","row_version":2,"title":"범죄는 방치하고 시민만 억압하는 체제","original":"Anarcho-Tyranny","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"권력이 폭력과 무질서를 묵인하면서 이에 맞서는 평범한 사람에게만 엄격한 통제를 가하는 디스토피아 설정. 실제 정치 제도의 일반적 설명이 아니라 작품 속 권력 구조를 가리킨다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-001565/index.html"},{"id":"MEJE-KW-001566","row_version":1,"title":"무정부주의를 혼란과 동일시하기","original":"Anarchy Is Chaos","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"무정부주의를 규칙 없는 폭력과 무질서로만 그리는 표현 관습. 국가 권력의 부재와 사회적 협력의 부재를 같은 뜻으로 취급할 때 생기는 단순화를 살핀다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001566/index.html"},{"id":"MEJE-KW-001567","row_version":1,"title":"팔다리 상실을 서사의 전환점으로 쓰기","original":"An Arm and a Leg","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 팔이나 다리를 잃는 사건이 삶의 방식과 관계를 바꾸는 전개. 사고의 충격뿐 아니라 이후 인물의 선택과 주변의 태도까지 이어져야 의미가 생긴다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-001567/index.html"},{"id":"MEJE-KW-001568","row_version":1,"title":"전투가 벌어지는 크리스마스","original":"An Ass-Kicking Christmas","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"평화와 재회를 기대하는 크리스마스 특별편을 액션 사건과 전투로 채우는 구성. 익숙한 축제 분위기가 위험한 상황과 대비된다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-001568/index.html"},{"id":"MEJE-KW-001569","row_version":1,"title":"유령처럼 보인 살아 있는 사람의 투사체","original":"An Astral Projection, Not a Ghost","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"죽은 사람의 혼처럼 나타난 존재가 사실은 살아 있는 사람의 몸 밖 투사였다는 반전. 부재한 육체와 보이는 형상을 따로 설명하는 세계 규칙이 필요하다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-001569/index.html"},{"id":"MEJE-KW-001570","row_version":1,"title":"낯선 종족을 잘못 고친 치료자","original":"Anatomically Ignorant Healing","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"다른 종의 몸을 잘 모르는 치료자가 선의로 고치려다 원래 형태와 다른 몸을 만들어 버리는 허구의 사건. 치료 의도와 결과의 불일치가 갈등이나 공포를 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-001570/index.html"},{"id":"MEJE-KW-001571","row_version":1,"title":"성적 장면의 비현실적 신체 묘사","original":"Anatomically Impossible Sex","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 성적 행위와 몸의 움직임을 실제 가능한 범위와 다르게 묘사하는 표현 관습. 장르적 과장과 자료 조사 부족을 구별해 읽는다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001571/index.html"},{"id":"MEJE-KW-001572","row_version":2,"title":"혼자만 다른 해부학으로 그린 인물","original":"Anatomy Anomaly","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"같은 작품의 다른 인물과 달리 특정 인물의 코·입·손가락 같은 신체 세부만 생략하거나 더 강조하는 그림 방식. 차이가 캐릭터의 인상을 만든다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-001572/index.html"},{"id":"MEJE-KW-001573","row_version":3,"title":"영혼을 여러 부분으로 나눈 설정","original":"Anatomy of the Soul","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13","ML-T01202","ML-T01203"],"summary":"영혼이 기억·의지·생명력처럼 서로 다른 기능의 부분으로 이루어졌다고 정한 세계관 규칙. 한 부분을 잃었을 때 무엇이 남는지가 갈등의 원천이 된다.","accent":"#497A73","tab":"#528982","facet":"세계관·규칙","bookmark":"영혼의 실재","entry_url":"cards/MEJE-KW-001573/index.html"}]}.cards;